#include "stdlib/blas/ext/base/zsome.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/real.h"
#include "stdlib/complex/float64/imag.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdbool.h>

/**
* Tests whether a double-precision complex floating-point strided array contains at least `k` truthy elements.
*
* @param N        number of indexed elements
* @param k        minimum number of truthy elements
* @param X        input array
* @param strideX  stride length
* @return         boolean result
*/
bool API_SUFFIX(stdlib_strided_zsome)( const CBLAS_INT N, const CBLAS_INT k, const stdlib_complex128_t *X, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_zsome_ndarray)( N, k, X, strideX, ox );
}

/**
* Tests whether a double-precision complex floating-point strided array contains at least `k` truthy elements using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param k        minimum number of truthy elements
* @param X        input array
* @param strideX  stride length
* @param offsetX  starting index
* @return         boolean result
*/
bool API_SUFFIX(stdlib_strided_zsome_ndarray)( const CBLAS_INT N, const CBLAS_INT k, const stdlib_complex128_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	stdlib_complex128_t v;
	CBLAS_INT cnt;
	CBLAS_INT ix;
	CBLAS_INT i;
	double re;
	double im;

	if ( N <= 0 ) {
		return false;
	}
	cnt = 0;
	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		v = X[ ix ];
		re = stdlib_complex128_real( v );
		im = stdlib_complex128_imag( v );
		if ( ( re != 0.0 && !stdlib_base_is_nan( re ) ) || ( im != 0.0 && !stdlib_base_is_nan( im ) ) ) {
			cnt += 1;
			if ( cnt >= k ) {
				return true;
			}
		}
		ix += strideX;
	}
	return false;
}
